//! Copies the keyboard vocabulary generated by Nix into `OUT_DIR`.
//!
//! The same shape as `ronoctua-bluetooth`'s, and for the same reason: the
//! declaration lives in `assets/keyboards.nix`, Nix turns it into Rust, and
//! generating it here would reimplement Nix logic (invariant 5).

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_KEYBOARDS_RS");

    let generated = env::var("RONOCTUA_KEYBOARDS_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_KEYBOARDS_RS is not set.\n\
             \n\
             The keyboard vocabulary is generated by Nix out of\n\
             assets/keyboards.nix. Enter the environment with `direnv allow`\n\
             (or `nix develop`), which sets the variable, or build through the flake\n\
             with `nix build`."
        )
    });

    println!("cargo:rerun-if-changed={generated}");

    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("keyboards.rs");
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("could not copy {generated} -> {destination:?}: {e}"));
}
